/**
 * Issue dependencies ("blocked by" links): recording and removing links, the
 * completion gate `IssueService` consults before an issue moves to `done`, and
 * the `issue_unblocked` notification once a blocker closes.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, subscribe, notify
 */
import { subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived, isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { notify } from "./notification-service";
import { issueResource, requireFound } from "./_support";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Issue, IssueDependency, IssueStatus } from "@/types/issue";
import type { Actor } from "@/types/member";
import type { Unsubscribe } from "@/types/event";

type BlockerInput = { orgId: OrgId; issueId: IssueId; blockerId: IssueId };

/** Raised when an issue is moved to `done` while a blocker is still open. */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: IssueId,
    readonly blockerIds: readonly IssueId[],
  ) {
    super(
      `Issue ${issueId} is blocked by open issue(s) ${blockerIds.join(", ")}`,
    );
    this.name = "IssueBlockedError";
  }
}

function isClosedStatus(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

/** Open = not archived and neither `done` nor `canceled`. */
function isOpen(issue: Issue): boolean {
  return !isArchived(issue) && !isClosedStatus(issue.status);
}

async function loadIssue(orgId: OrgId, issueId: IssueId): Promise<Issue> {
  return requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
}

async function loadBlockers(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const ids = await dependencyRepo.listBlockerIds(orgId, issueId);
  const blockers: Issue[] = [];
  for (const id of ids) {
    const blocker = await issueRepo.findIssueById(orgId, id);
    if (blocker) blockers.push(blocker);
  }
  return blockers.sort(
    (a, b) => a.number - b.number || a.id.localeCompare(b.id),
  );
}

async function openBlockerIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  return (await loadBlockers(orgId, issueId))
    .filter(isOpen)
    .map((blocker) => blocker.id);
}

/**
 * The completion gate. Only a move to `done` is gated; every other status
 * change stays allowed regardless of blockers.
 */
export async function assertCanTransition(
  orgId: OrgId,
  issueId: IssueId,
  to: IssueStatus,
): Promise<void> {
  if (to !== "done") return;
  const open = await openBlockerIds(orgId, issueId);
  if (open.length > 0) throw new IssueBlockedError(issueId, open);
}

/** True when `from` can already reach `target` by following blocker links. */
async function reaches(
  orgId: OrgId,
  from: IssueId,
  target: IssueId,
): Promise<boolean> {
  const seen = new Set<IssueId>([from]);
  const queue: IssueId[] = [from];
  while (queue.length > 0) {
    const current = queue.shift() as IssueId;
    if (current === target) return true;
    for (const next of await dependencyRepo.listBlockerIds(orgId, current)) {
      if (!seen.has(next)) {
        seen.add(next);
        queue.push(next);
      }
    }
  }
  return false;
}

export async function addBlocker(
  actor: Actor,
  input: BlockerInput,
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = await loadIssue(input.orgId, input.issueId);
  const blocker = await loadIssue(input.orgId, input.blockerId);
  assertCan(actor, "issue:update", issueResource(issue));

  if (issue.id === blocker.id) {
    throw new Error(`Issue ${issue.id} cannot block itself`);
  }
  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Issue", blocker.id, blocker);

  const existing = await dependencyRepo.findDependency(
    input.orgId,
    issue.id,
    blocker.id,
  );
  if (existing) return existing;

  // The new edge issue → blocker closes a cycle iff the blocker already
  // (transitively) waits on the issue.
  if (await reaches(input.orgId, blocker.id, issue.id)) {
    throw new Error(
      `Issue ${blocker.id} already depends on ${issue.id}; the link would create a cycle`,
    );
  }

  return dependencyRepo.insertDependency(
    input.orgId,
    issue.id,
    blocker.id,
    actor.userId,
  );
}

export async function removeBlocker(
  actor: Actor,
  input: BlockerInput,
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const issue = await loadIssue(input.orgId, input.issueId);
  assertCan(actor, "issue:update", issueResource(issue));

  return dependencyRepo.deleteDependency(
    input.orgId,
    issue.id,
    input.blockerId,
  );
}

/** Live blockers of `issueId` (open or closed), by issue number. */
export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = await loadIssue(orgId, issueId);
  assertCan(actor, "issue:read", issueResource(issue));

  return (await loadBlockers(orgId, issue.id)).filter(
    (blocker) => !isArchived(blocker),
  );
}

/**
 * A blocker just went from open to closed: notify the assignee of every live,
 * still-open issue it blocks that has no open blocker left.
 */
async function notifyUnblocked(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: UserId | null,
): Promise<void> {
  for (const blockedId of await dependencyRepo.listBlockedIds(
    orgId,
    blockerId,
  )) {
    const blocked = await issueRepo.findIssueById(orgId, blockedId);
    if (!blocked || !isOpen(blocked) || blocked.assigneeId === null) continue;
    if ((await openBlockerIds(orgId, blocked.id)).length > 0) continue;

    await notify(orgId, "issue_unblocked", [blocked.assigneeId], {
      title: "Your issue is unblocked",
      body: `Issue ${blocked.id} has no open blockers left`,
      href: `/issues/${blocked.id}`,
      actorId,
    });
  }
}

export function registerIssueDependencyListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.status_changed", async (payload) => {
      if (isClosedStatus(payload.from) || !isClosedStatus(payload.to)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
    subscribe("issue.archived", async (payload) => {
      // Archiving never touches the status, so the row still carries the
      // status the blocker had just before it was archived.
      const archived = await issueRepo.findIssueById(
        payload.orgId,
        payload.issueId,
      );
      if (!archived || isClosedStatus(archived.status)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

