import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import * as issueService from "@/server/services/issue-service";
import * as dep from "@/server/services/issue-dependency-service";
import * as notifRepo from "@/server/repositories/notification-repository";
import { registerEventHandlers } from "@/server/services/event-registry";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => cleanup());

describe("deps", () => {
  it("works", async () => {
    const t = await createTenant("deps");
    const admin = t.actors.admin;
    const mk = (title: string, assigneeId: any = null) =>
      issueService.createIssue(admin, issueInput(t.org.id, t.project.id, { title, assigneeId }));
    const a = await mk("Issue A", t.actors.member.userId);
    const b = await mk("Issue B");
    const c = await mk("Issue C");
    await dep.addBlocker(admin, { orgId: t.org.id, issueId: a.id, blockerId: c.id });
    await dep.addBlocker(admin, { orgId: t.org.id, issueId: a.id, blockerId: b.id });
    await dep.addBlocker(admin, { orgId: t.org.id, issueId: a.id, blockerId: b.id });
    await expect(dep.addBlocker(admin, { orgId: t.org.id, issueId: b.id, blockerId: a.id })).rejects.toThrow();
    await expect(dep.addBlocker(admin, { orgId: t.org.id, issueId: a.id, blockerId: a.id })).rejects.toThrow();
    expect((await dep.listBlockers(admin, t.org.id, a.id)).map((i) => i.title)).toEqual(["Issue B", "Issue C"]);
    await expect(issueService.moveIssue(admin, { orgId: t.org.id, issueId: a.id, toStatus: "done", toIndex: 0 } as any)).rejects.toBeInstanceOf(dep.IssueBlockedError);
    await issueService.changeIssueStatus(admin, { orgId: t.org.id, issueId: b.id, status: "done" });
    const list = async () => (await notifRepo.listNotifications({ orgId: t.org.id, recipientId: t.actors.member.userId, unreadOnly: false, limit: 50 } as any)).items.filter((n) => n.kind === "issue_unblocked");
    expect(await list()).toHaveLength(0);
    await issueService.archiveIssue(admin, t.org.id, c.id);
    const ns = await list();
    expect(ns).toHaveLength(1);
    expect(ns[0].href).toBe(`/issues/${a.id}`);
    await issueService.changeIssueStatus(admin, { orgId: t.org.id, issueId: a.id, status: "done" });
    expect(await dep.removeBlocker(admin, { orgId: t.org.id, issueId: a.id, blockerId: b.id })).toBe(true);
    expect(await dep.removeBlocker(admin, { orgId: t.org.id, issueId: a.id, blockerId: b.id })).toBe(false);
  });
});
